    setLookupProgress(64);
    setLookupStepIndex(3);
  });
  scheduleLookup(2500, () => {
    setLookupProgress(80);
    setLookupStepIndex(4);
  });
  scheduleLookup(3300, () => {
    setFlowState((prev) => {
      const baseContext = resolveFlowContext(
        prev.context as Partial<CustomerContext> & {
          representativeName?: string;
          kycNotes?: string;
          address?: string;
